    )


def _object_row(
    path: Path, line_number: int, row: object, kind: str
) -> dict[str, object]:
    if not isinstance(row, dict):
        raise _shape_error(path, line_number, kind)
    return cast("dict[str, object]", row)


def _required_int(
    data: dict[str, object], key: str, *, path: Path, line_number: int, kind: str
) -> int:
    value = data.get(key)
    if not isinstance(value, int) or isinstance(value, bool):
        raise _shape_error(path, line_number, kind)
    return value


def _required_str(
    data: dict[str, object], key: str, *, path: Path, line_number: int, kind: str
) -> str:
    value = data.get(key)
    if not isinstance(value, str):
        raise _shape_error(path, line_number, kind)
    return value


def _optional_str(
    data: dict[str, object],
    key: str,
    *,
    path: Path,
    line_number: int,
    kind: str,
    default: str = "",
) -> str:
    if key not in data:
        return default
    return _required_str(data, key, path=path, line_number=line_number, kind=kind)


def _required_bool(
    data: dict[str, object], key: str, *, path: Path, line_number: int, kind: str
) -> bool:
    value = data.get(key)
    if not isinstance(value, bool):
        raise _shape_error(path, line_number, kind)
    return value


def _required_str_list(
    data: dict[str, object], key: str, *, path: Path, line_number: int, kind: str
) -> list[str]:
    value = data.get(key)
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise _shape_error(path, line_number, kind)
    return [str(item) for item in cast("list[str]", value)]


def _optional_str_list(
    data: dict[str, object], key: str, *, path: Path, line_number: int, kind: str
